/**
 * Morocco Tourism Areas Master Registry
 * Single source of truth for all cities, neighborhoods, villages, and areas across Morocco.
 * Generated from Morocco_Tourism_Areas_Master_Database (9).xlsx
 * 
 * TOURISM_STATUS values:
 * - 'Touristic'     → Primary tourist destinations with listings/attractions
 * - 'Mixed'         → Areas with services/transport but limited tourism listings
 * - 'Non-touristic' → Residential/industrial areas (excluded from tourist tools)
 */

export type TourismStatus = 'Touristic' | 'Mixed' | 'Non-touristic';
export type AreaType = 'Neighborhood' | 'Square' | 'Area' | 'Industrial/Creative District' | 'Town' | 'Village' | 'Valley' | 'Mountain Area' | 'Coastal Area' | 'Beach' | 'Lagoon' | 'Natural Area' | 'National Park' | 'Historic Area' | 'Historic Landmark' | 'Archaeological Site' | 'Marina Area' | 'Resort Area' | 'Urban Area' | 'Port' | 'Mountain Resort' | 'Natural Site' | 'Nature Reserve' | 'Lake' | 'Ksar' | 'Oasis' | 'Dunes' | 'Park' | 'Beach Area' | 'Coastal Village' | 'Desert Site' | 'Landmark Area' | 'Town/Area' | 'Medina' | 'Agricultural/Coastal' | 'Natural Landmark' | 'Village/Nature Area' | 'Corniche' | 'Port Area' | 'Village/Beach' | 'Historic Site' | 'Forest' | 'Marina/Resort' | 'Gorges' | 'Palmeraie' | 'Roman Ruins' | 'Happy Valley' | 'Mountain Villages' | 'Neighborhood/Beach' | 'Village Area' | 'Historic Town' | 'Industrial/Residential';

export type StandardSeason = 'Summer' | 'Winter' | 'Spring' | 'Autumn' | 'Year-round' | 'Shoulder';

export function normalizeBestSeason(seasonStr: string): StandardSeason {
  if (!seasonStr || seasonStr === '-') return 'Year-round';
  const s = seasonStr.toLowerCase();
  if (s.includes('year') || s.includes('all')) return 'Year-round';
  
  // Specific month ranges
  if (s.includes('jun-sep') || s === 'summer') return 'Summer';
  if (s.includes('dec-mar') || s === 'winter') return 'Winter';
  if (s.includes('oct-nov') || s === 'autumn' || s === 'fall') return 'Autumn';
  if (s.includes('mar-may') || s === 'spring') return 'Spring';
  
  // Multi-season shoulder ranges
  if (s.includes('sep-may') || s.includes('oct-apr') || s.includes('sep-apr')) return 'Shoulder';
  if (s.includes('mar-oct') || s.includes('apr-oct')) return 'Shoulder';

  if (s.includes('jun') || s.includes('jul') || s.includes('aug') || s.includes('summer')) return 'Summer';
  if (s.includes('dec') || s.includes('jan') || s.includes('feb') || s.includes('winter')) return 'Winter';
  if (s.includes('mar') || s.includes('apr') || s.includes('may') || s.includes('spring')) return 'Spring';
  if (s.includes('sep') || s.includes('oct') || s.includes('nov') || s.includes('autumn') || s.includes('fall')) return 'Autumn';

  return 'Shoulder';
}

export interface TourismArea {
  id: number;
  region: string;
  province: string;
  cityBase: string;          // Matches website city IDs (marrakech, fes, agadir, etc.)
  areaVillage: string;       // Specific area/neighborhood/village name
  type: AreaType;
  tourismStatus: TourismStatus;
  tourismCategory: string;
  mainAttractions: string;
  bestSeason: StandardSeason | string;
  recommendedStay: string;
  notes: string;
}

