// ============================================================
// DERIVED LISTS & LOOKUPS
// ============================================================

/** All areas with tourismStatus === 'Touristic' (197 entries) */
export const TOURISTIC_AREAS = TOURISM_AREAS_MASTER.filter(a => a.tourismStatus === 'Touristic');

/** All areas with tourismStatus === 'Mixed' (37 entries) */
export const MIXED_AREAS = TOURISM_AREAS_MASTER.filter(a => a.tourismStatus === 'Mixed');

/** All areas with tourismStatus === 'Non-touristic' (14 entries) — excluded from tourist-facing tools */
export const NON_TOURISTIC_AREAS = TOURISM_AREAS_MASTER.filter(a => a.tourismStatus === 'Non-touristic');

/** Touristic + Mixed (234 entries) — for infrastructure/utility tools */
export const TOURISTIC_AND_MIXED = TOURISM_AREAS_MASTER.filter(a => a.tourismStatus !== 'Non-touristic');

/** All 270 entries (for admin/debug) */
export const ALL_AREAS = TOURISM_AREAS_MASTER;

// ============================================================
// CITY-BASE AGGREGATIONS (maps website cityId → areas)
// ============================================================

/** Unique cityBase values present in the master list */
export const ALL_CITY_BASES = [...new Set(TOURISM_AREAS_MASTER.map(a => a.cityBase))];

/** Get all areas for a given cityBase (matches website cityId) */
export function getAreasByCityBase(cityBase: string): TourismArea[] {
  return TOURISM_AREAS_MASTER.filter(a => a.cityBase === cityBase);
}

/** Get only Touristic areas for a given cityBase */
export function getTouristicAreasByCityBase(cityBase: string): TourismArea[] {
  return TOURISTIC_AREAS.filter(a => a.cityBase === cityBase);
}

/** Get Touristic + Mixed areas for a given cityBase */
export function getTouristicAndMixedAreasByCityBase(cityBase: string): TourismArea[] {
  return TOURISTIC_AND_MIXED.filter(a => a.cityBase === cityBase);
}

/** Get unique areaVillage names for a cityBase (Touristic only) */
export function getTouristicAreaNamesByCityBase(cityBase: string): string[] {
  return getTouristicAreasByCityBase(cityBase).map(a => a.areaVillage);
}

/** Get unique areaVillage names for a cityBase (Touristic + Mixed) */
export function getTouristicAndMixedAreaNamesByCityBase(cityBase: string): string[] {
  return getTouristicAndMixedAreasByCityBase(cityBase).map(a => a.areaVillage);
}

// ============================================================
// REGION / PROVINCE LOOKUPS
// ============================================================

/** Get all areas in a region */
export function getAreasByRegion(region: string): TourismArea[] {
  return TOURISM_AREAS_MASTER.filter(a => a.region === region);
}

/** Get Touristic areas in a region */
export function getTouristicAreasByRegion(region: string): TourismArea[] {
  return TOURISTIC_AREAS.filter(a => a.region === region);
}

/** Unique regions in the database */
export const ALL_REGIONS = [...new Set(TOURISM_AREAS_MASTER.map(a => a.region))];

/** Unique provinces in the database */
export const ALL_PROVINCES = [...new Set(TOURISM_AREAS_MASTER.map(a => a.province))];

// ============================================================
// UTILITIES FOR TOOL CONSUMERS
// ============================================================

/**
 * Filter function type for tools to choose their area scope
 */
export type AreaFilter = 'touristic' | 'touristic_and_mixed' | 'all';

/**
 * Get areas for a tool based on its filter requirement.
 * 
 * @param cityBase - Website city ID (e.g., 'marrakech', 'fes', 'agadir')
 * @param filter - 'touristic' | 'touristic_and_mixed' | 'all'
 * @returns Array of TourismArea matching the criteria
 * 
 * TOOL MAPPING:
 * - 'touristic' → Finder (Eat/Sleep/Shop/Things/Activities), Matchmaker, City Pages, Travel Essentials, Dashboard
 * - 'touristic_and_mixed' → Planner, Transport/Move Around, Budget, Savvy, Safety, Language, Journal, Heatmap
 * - 'all' → Admin/debug only (includes Non-touristic)
 */
export function getAreasForTool(cityBase: string, filter: AreaFilter = 'touristic'): TourismArea[] {
  switch (filter) {
    case 'touristic':
      return getTouristicAreasByCityBase(cityBase);
    case 'touristic_and_mixed':
      return getTouristicAndMixedAreasByCityBase(cityBase);
    case 'all':
      return getAreasByCityBase(cityBase);
    default:
      return getTouristicAreasByCityBase(cityBase);
  }
}

/**
 * Get just the areaVillage names for a tool (convenience)
 */
export function getAreaNamesForTool(cityBase: string, filter: AreaFilter = 'touristic'): string[] {
  return getAreasForTool(cityBase, filter).map(a => a.areaVillage);
}

/**
 * Get area count summary for a city (useful for UI badges)
 */
export function getCityAreaSummary(cityBase: string): { touristic: number; mixed: number; nonTouristic: number; total: number } {
  const areas = getAreasByCityBase(cityBase);
  return {
    touristic: areas.filter(a => a.tourismStatus === 'Touristic').length,
    mixed: areas.filter(a => a.tourismStatus === 'Mixed').length,
    nonTouristic: areas.filter(a => a.tourismStatus === 'Non-touristic').length,
    total: areas.length
  };
}

// ============================================================
// EXPORTS FOR BACKWARDS COMPATIBILITY (legacy cities.ts sync)
// ============================================================

/**
 * Returns neighborhood names formatted for cities.ts compatibility.
 * Use this to sync cities.ts neighborhoods with the master database.
 */
export function getLegacyNeighborhoods(cityBase: string, includeMixed: boolean = false): string[] {
  const filter: AreaFilter = includeMixed ? 'touristic_and_mixed' : 'touristic';
  return getAreaNamesForTool(cityBase, filter);
}

/**
 * Get all primary city IDs that have at least one touristic area.
 * Used by CatalogPanel to list all cities with touristic content.
 */
export function getPrimaryCitiesWithTouristicAreas(): string[] {
  return ALL_CITY_BASES.filter(cityBase => {
    const areas = getTouristicAreasByCityBase(cityBase);
    return areas.length > 0;
  });
}

/**
 * Get city display name for a cityBase (from the first touristic area entry)
 */
export function getCityDisplayName(cityBase: string): string {
  const area = TOURISTIC_AREAS.find(a => a.cityBase === cityBase);
  return area ? area.areaVillage : cityBase;
}